export const code = async (inputs) => {
  // W50 / PAR-8 / ADR-0034 / ADR-0043 / ADR-0046: рендер карточки онбординга +
  // план записи. Пишет только в свой вывод: таблицы трогают шаги веток,
  // отправка — edit-шаги веток. writeKind finish_lite (повторное касание) —
  // тем же кодом, но ветка пропускает запись users: профиль уже в таблице,
  // пустым не затираем. writeKind finish_no_event (ADR-0034: онбординг на
  // голый /start, без диплинка события) — профиль пишется, регистрация нет:
  // создавать её не на что.
  // ADR-0043: отдельного экрана согласия и экрана «Всё верно?» нет. Входная
  // карточка (reg-start/step_9, menu/step_4) несёт и why, и текст согласия;
  // при ob:agree пишем согласие и сразу спрашиваем работу. Чистое имя из
  // Telegram принимается без шага подтверждения; подозрительное — прежний
  // ручной ввод. Выбор города ведёт прямо в finish.
  // ADR-0046: город спрашивается да/нет («Вы из Ташкента?»): «Да» — сразу
  // finish с городом «Ташкент», «Нет» — карточка свободного ввода
  // (onb.ask_city_input → ob_await_city).
  // W76: финальная карточка несёт дату/адрес/карту (как карточка события), а
  // в билет добавляется ссылка «Добавить в календарь» (Google Calendar).
  // W114: выбран язык (ob:lang:*) — кладём его в draft.profile.lang и идём
  // существующей веткой `card` (запись сессии + отрисовка карточки согласия):
  // users.lang запишется в finish/finish_no_event, а локаль промежуточных
  // прогонов tg-router берёт из draft (ru/uz/en). Новых табличных шагов нет —
  // платформа сейчас не даёт создавать steps на tables 0.4.6 через MCP.
  const texts = (inputs.texts && typeof inputs.texts === 'object') ? inputs.texts : {};
  const t = (key, vars) => {
    let s = String(texts[key] === undefined || texts[key] === null ? key : texts[key]);
    if (vars) Object.keys(vars).forEach((k) => { s = s.split('{' + k + '}').join(String(vars[k])); });
    return s;
  };
  const esc = (v) => String(v === undefined || v === null ? '' : v)
    .replace(/\\/g, '\\\\')
    .replace(/([_*\[\]()~`>#+\-=|{}.!])/g, '\\$1');
  const str = (v) => String(v === undefined || v === null ? '' : v);
  const arr = (src) => Array.isArray(src) ? src : (src && Array.isArray(src.records) ? src.records : []);
  const flat = (rec) => {
    const out = {};
    const cells = (rec && rec.cells) || {};
    Object.keys(cells).forEach((fid) => {
      const c = cells[fid];
      if (c && typeof c === 'object' && typeof c.fieldName === 'string') out[c.fieldName] = str(c.value);
    });
    return out;
  };
  const TZ = 'Asia/Tashkent';
  const dateFmt = new Intl.DateTimeFormat('ru-RU', { timeZone: TZ, day: 'numeric', month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });
  const fmt = (iso) => {
    if (!iso) return '';
    const s = /[Zz]$/.test(iso) || /[+-][0-9]{2}:?[0-9]{2}$/.test(iso) ? iso : iso + 'Z';
    const d = new Date(s);
    return isNaN(d.getTime()) ? '' : dateFmt.format(d);
  };
  const parseIso = (s) => Date.parse(/[Zz]$/.test(s) || /[+-][0-9]{2}:?[0-9]{2}$/.test(s) ? s : s + 'Z');
  const ev = arr(inputs.eventRows).map(flat)[0] || {};
  // W131 (ADR-0053): на онлайне билет-сообщение не обещает QR.
  const online = str(ev.format) === 'online';
  const p = (inputs.parsed && typeof inputs.parsed === 'object') ? inputs.parsed : {};
  const action = str(p.action);
  const prof = (p.profile && typeof p.profile === 'object') ? p.profile : {};
  const text = str(p.text);
  const lat = Number(ev.lat);
  const lon = Number(ev.lon);
  // W76/W72: пустые координаты и (0,0) — не гео (Number('') === 0, баг #124);
  // координаты должны быть в диапазоне.
  const hasGeo = str(ev.lat) !== '' && str(ev.lon) !== '' && isFinite(lat) && isFinite(lon) && lat >= -90 && lat <= 90 && lon >= -180 && lon <= 180 && !(lat === 0 && lon === 0);
  const mapsUrl = hasGeo ? ('https://yandex.uz/maps/?ll=' + lon + '%2C' + lat + '&z=17&pt=' + lon + '%2C' + lat) : '';
  // W76: Google Calendar без ключей; дата в UTC-формате YYYYMMDDTHHMMSSZ.
  const utcStamp = (iso) => {
    const s = str(iso);
    if (!s) return '';
    const ms = parseIso(s);
    return isFinite(ms) ? new Date(ms).toISOString().replace(/[-:]/g, '').replace(/\.\d{3}/, '') : '';
  };
  const calUrl = (() => {
    const start = utcStamp(ev.starts_at);
    if (!start) return '';
    let end = utcStamp(ev.ends_at);
    if (!end) {
      const ms = parseIso(str(ev.starts_at));
      end = isFinite(ms) ? new Date(ms + 3600000).toISOString().replace(/[-:]/g, '').replace(/\.\d{3}/, '') : '';
    }
    if (!start || !end) return '';
    const params = ['action=TEMPLATE', 'text=' + encodeURIComponent(str(ev.title)), 'dates=' + start + '/' + end];
    if (str(ev.address)) params.push('location=' + encodeURIComponent(str(ev.address)));
    return 'https://calendar.google.com/calendar/render?' + params.join('&');
  })();
  const eventFacts = (() => {
    const facts = [];
    if (ev.title) facts.push('*' + esc(ev.title) + '*');
    const meta = [];
    if (ev.starts_at) meta.push('📅 ' + esc(fmt(ev.starts_at)) + (ev.ends_at ? ' — ' + esc(fmt(ev.ends_at)) : ''));
    if (ev.address) meta.push('📍 ' + esc(ev.address));
    if (mapsUrl) meta.push('🗺 [Открыть на карте](' + mapsUrl + ')');
    if (meta.length) facts.push(meta.join('\n'));
    return facts.join('\n\n');
  })();
  const eventCard = (extra) => {
    const lines = [];
    if (ev.title) lines.push('*' + esc(ev.title) + '*');
    if (ev.description) lines.push(esc(ev.description));
    const facts = [];
    if (ev.starts_at) facts.push('📅 ' + esc(fmt(ev.starts_at)) + (ev.ends_at ? ' — ' + esc(fmt(ev.ends_at)) : ''));
    if (ev.address) facts.push('📍 ' + esc(ev.address));
    if (mapsUrl) facts.push('🗺 [Открыть на карте](' + mapsUrl + ')');
    if (ev.reg_deadline_at) facts.push('⏳ ' + esc(t('event.card.deadline_short', { when: fmt(ev.reg_deadline_at) })));
    if (facts.length) lines.push(facts.join('\n'));
    if (extra) lines.push(esc(extra));
    return lines.join('\n\n');
  };
  const btn = (label, cb) => ({ text: label, callback_data: cb });
  const kb = (rows) => ({ inline_keyboard: rows });
  const fullName = (str(p.firstName).trim() + ' ' + str(p.lastName).trim()).trim();
  let writeKind = 'card';
  let cardText = '';
  let replyMarkup = {};
  let nextStep = '';
  let profile = Object.assign({}, prof);
  let saveConsent = false;
  let lang = '';
  let ticketText = '';
  let ticketReplyMarkup = {};
  const now = str(p.now) || new Date().toISOString();
  const cardId = Number(p.cardMessageId) || 0;
  const eventId = str(p.eventId);
  const miniappUrl = str(inputs.miniappUrl);
  const miniappBase = miniappUrl.endsWith('/') ? miniappUrl.slice(0, -1) : miniappUrl;
  const draftOf = (step, pr) => JSON.stringify({ eventId: eventId, utm: str(p.utm), cardMessageId: cardId, profile: pr || {}, step: step });
  let draftJson = draftOf(nextStep, profile);
  const ticketRows = (withCalendar) => {
    const rows = [[{ text: t('ticket.btn.open'), web_app: { url: miniappBase + '/#/ticket?event_id=' + eventId } }]];
    if (withCalendar && calUrl) rows.push([{ text: t('event.card.btn_calendar'), url: calUrl }]);
    return rows;
  };
  if (action === 'set_lang') {
    // W114: язык выбран — кладём его в draft.profile.lang и показываем карточку
    // согласия на выбранном языке (локаль этого прогона уже выставлена
    // tg-router'ом по колбэку ob:lang:*). Ветка `card` сохранит draft и
    // отредактирует карточку; в finish users.lang уедет вместе с профилем.
    writeKind = 'card';
    lang = str(p.lang);
    profile = Object.assign({}, prof, { lang: lang });
    cardText = eventCard(t('onb.why') + '\n\n' + t('onb.consent'));
    replyMarkup = kb([[btn(t('onb.btn.agree'), 'ob:agree'), btn(t('onb.btn.details'), 'ob:details')]]);
    nextStep = 'ob_consent';
  } else if (action === 'show_details') {
    cardText = eventCard(t('onb.details'));
    replyMarkup = kb([[btn(t('onb.btn.understood'), 'ob:understood'), btn(t('reg.consent_pdn.btn_no'), 'ob:decline')]]);
    nextStep = 'ob_details';
  } else if (action === 'consent_namecheck') {
    // ADR-0043: согласие пишем здесь же (ветка ROUTER `consent`), до первого
    // поля ПД — это и держит PAR-1 без отдельного экрана согласия.
    writeKind = 'consent';
    saveConsent = true;
    const chk = (p.check && typeof p.check === 'object') ? p.check : { suspicious: true };
    if (chk.suspicious) {
      // Подозрительное имя — объясняем и просим руками (единственный путь к
      // ob_await_name).
      cardText = eventCard(t('onb.suspect', { name: fullName || '?' }));
      replyMarkup = kb([[btn(t('onb.btn.write_name'), 'ob:fixname')]]);
      nextStep = 'ob_name';
    } else {
      // Чистое имя из Telegram принимаем молча и сразу спрашиваем работу.
      // prof несёт lang, выбранный на первой карточке (W114) — сохраняем.
      profile = Object.assign({}, prof, { first: str(p.firstName).trim(), last: str(p.lastName).trim() });
      cardText = eventCard(t('onb.ask_work'));
      replyMarkup = {};
      nextStep = 'ob_await_work';
    }
  } else if (action === 'show_ask_name') {
    cardText = eventCard(t('onb.ask_name'));
    replyMarkup = {};
    nextStep = 'ob_await_name';
  } else if (action === 'text_name') {
    const parts = text.split(/\s+/).filter((w) => w.length >= 2);
    if (parts.length >= 2 && text.length <= 80) {
      profile = Object.assign({}, prof, { first: parts[0], last: parts.slice(1).join(' ') });
      cardText = eventCard(t('onb.ask_work'));
      replyMarkup = {};
      nextStep = 'ob_await_work';
    } else {
      cardText = eventCard(t('profile.err') + '\n' + t('onb.ask_name'));
      replyMarkup = {};
      nextStep = 'ob_await_name';
    }
  } else if (action === 'text_work') {
    const ci = text.indexOf(',');
    const position = (ci >= 0 ? text.slice(0, ci) : text).trim();
    const company = (ci >= 0 ? text.slice(ci + 1) : '').trim();
    if (position !== '' && text.length <= 200) {
      profile = Object.assign({}, prof, { position: position, company: company });
      cardText = eventCard(t('onb.ask_city'));
      replyMarkup = kb([[btn(t('common.btn.yes'), 'ob:city:yes'), btn(t('common.btn.no'), 'ob:city:no')]]);
      nextStep = 'ob_city';
    } else {
      cardText = eventCard(t('profile.err') + '\n' + t('onb.ask_work'));
      replyMarkup = {};
      nextStep = 'ob_await_work';
    }
  } else if (action === 'show_ask_city') {
    cardText = eventCard(t('onb.ask_city_input'));
    replyMarkup = {};
    nextStep = 'ob_await_city';
  } else if (action === 'finish' || action === 'finish_lite') {
    // ADR-0034: первое касание без диплинка (eventId пуст) не может создать
    // регистрацию — создавать её не на что. Профиль и оба согласия пишутся
    // так же, финальная карточка и текст — другие (см. writeKind ниже).
    const noEvent = action === 'finish' && eventId === '';
    writeKind = action === 'finish_lite' ? 'finish_lite' : (noEvent ? 'finish_no_event' : 'finish');
    profile = Object.assign({}, prof);
    // ADR-0043/ADR-0046: город приходит сюда из колбэка/текста (экрана review
    // нет) — домешиваем его в профиль перед записью.
    if (str(p.city) !== '') profile.city = str(p.city);
    if (action === 'finish_lite') {
      // Владелец (после W59, W60): consent на рассылку уже дан или отклонён
      // при первом заполнении профиля — без него profile_completed_at не
      // взводится, а finish_lite достижим только с заполненным профилем
      // (reg-start/step_3, гейт «профиль заполнен → register»).
      // Переспрашивать не нужно: сразу финальная карточка с датой/адресом,
      // билет вторым сообщением, сессия закрывается (следующего колбэка нет).
      cardText = '*' + esc(t('reg.done.header')) + '*' + (eventFacts ? '\n\n' + eventFacts : '');
      replyMarkup = {};
      nextStep = '';
      ticketText = [esc(t('ticket.header')), esc(t(online ? 'ticket.hint_online' : 'ticket.hint'))].join('\n\n');
      ticketReplyMarkup = { inline_keyboard: ticketRows(true) };
    } else if (noEvent) {
      cardText = '*' + esc(t('profile.saved.header')) + '*' + '\n\n' + esc(t('profile.saved')) + '\n' + esc(t('reg.consent_marketing.ask'));
      replyMarkup = kb([[{ text: t('reg.consent_marketing.btn_yes'), callback_data: 'reg:mkt:yes' }, { text: t('reg.consent_marketing.btn_no'), callback_data: 'reg:mkt:no' }]]);
      nextStep = 'await_marketing';
    } else {
      cardText = '*' + esc(t('reg.done.header')) + '*' + (eventFacts ? '\n\n' + eventFacts : '') + '\n' + esc(t('reg.consent_marketing.ask'));
      replyMarkup = kb([[{ text: t('reg.consent_marketing.btn_yes'), callback_data: 'reg:mkt:yes' }, { text: t('reg.consent_marketing.btn_no'), callback_data: 'reg:mkt:no' }]]);
      nextStep = 'await_marketing';
    }
  } else if (action === 'declined') {
    writeKind = 'declined';
    cardText = eventCard(eventId === '' ? t('reg.consent_pdn.declined_no_link') : t('reg.consent_pdn.declined'));
    replyMarkup = {};
    nextStep = '';
  } else {
    return { writeKind: 'ignore' };
  }
  draftJson = draftOf(nextStep, profile);
  return { writeKind: writeKind, cardText: cardText, replyMarkup: replyMarkup, nextStep: nextStep, draftJson: draftJson, profile: profile, saveConsent: saveConsent, lang: lang, eventId: eventId, utm: str(p.utm), cardMessageId: cardId, now: now, ticketText: ticketText, ticketReplyMarkup: ticketReplyMarkup };
};

export const code = async (inputs) => {
  // W50 / PAR-8 / ADR-0032 / ADR-0043 / ADR-0046 / W133: онбординг C — разбор
  // входа и маршрутизация. Чистая функция: тексты не нужны, только ветвление и
  // эвристика имени. ADR-0043: отдельного экрана согласия нет (входная
  // карточка и есть согласие, колбэк ob:agree); чистое имя из Telegram не
  // подтверждается шагом; экрана «Всё верно?» нет — город ведёт сразу в
  // finish. ADR-0046: город спрашивается да/нет («Вы из Ташкента?»).
  const str = (v) => String(v === undefined || v === null ? '' : v);
  const cb = str(inputs.callbackData);
  const text = str(inputs.messageText).trim();
  let draft = {};
  try { draft = JSON.parse(str(inputs.sessionDraft) || '{}'); } catch (e) { draft = {}; }
  const step = str(draft.step);
  const eventId = str(draft.eventId);
  const utm = str(draft.utm);
  const telegramId = str(inputs.telegramId);
  const cardMessageId = Number(draft.cardMessageId);
  const profile = (draft.profile && typeof draft.profile === 'object') ? draft.profile : {};
  // Эвристика «подозрительное имя» (ADR-0032 п.4): только роутинг, не запрет.
  // Порядок проверок — из ADR: короткое → цифра → эмодзи → мусор → длинное.
  const nameCheck = (first, last) => {
    const fn = str(first).trim(), ln = str(last).trim();
    if (fn.length < 2 || ln.length < 2) return { suspicious: true, reason: 'too_short' };
    const both = fn + ' ' + ln;
    if (/[0-9]/.test(both)) return { suspicious: true, reason: 'has_digit' };
    if (/\p{Extended_Pictographic}/u.test(both)) return { suspicious: true, reason: 'has_emoji' };
    // Правка (2026-09-20): было `/regex/.u.test(...)` — точка перед `u`
    // отрывала флаг в обращение к несуществующему свойству regex-объекта
    // (undefined.test → TypeError). Падало на каждом «чистом» имени, то
    // есть почти на любом реальном входе в consent_namecheck.
    if (/[^\p{L}\s\-'’‘ʼʻ`]/u.test(both)) return { suspicious: true, reason: 'bad_chars' };
    if (both.length > 40) return { suspicious: true, reason: 'too_long' };
    return { suspicious: false, reason: '' };
  };
  const starts = (s, p) => s.indexOf(p) === 0;
  const out = (action, extra) => Object.assign({
    action: action, eventId: eventId,
    // W102: tables-find-records fail-closed на пустом eq — фильтр step_2
    // читает eventIdOrNone; при онбординге без события (draft.eventId: '')
    // шаг не падает, а честно не находит событие (ветка finish_no_event).
    eventIdOrNone: eventId !== '' ? eventId : '__none__',
    utm: utm,
    cardMessageId: isFinite(cardMessageId) && cardMessageId > 0 ? cardMessageId : 0,
    firstName: str(inputs.firstName), lastName: str(inputs.lastName),
    profile: profile, text: text,
    check: nameCheck(inputs.firstName, inputs.lastName),
    regId: eventId !== '' && telegramId !== '' ? eventId + '-' + telegramId : '',
    now: new Date().toISOString()
  }, extra || {});
  if (starts(cb, 'ob:')) {
    const sub = cb.slice(3);
    // W114: выбор языка на первой карточке онбординга (шаг ob_lang). Значение
    // сужаем до ru|uz|en: оно станет локалью этого же прогона (tg-router по
    // колбэку) и записью users.lang; чужое не пишем и не роняем `$t`.
    if (starts(sub, 'lang:') && step === 'ob_lang') {
      const code = sub.slice('lang:'.length).trim().toLowerCase();
      if (code === 'ru' || code === 'uz' || code === 'en') return out('set_lang', { lang: code });
      return out('ignore');
    }
    // ADR-0043: входная карточка (reg-start/step_9, menu/step_4) несёт сразу
    // и «зачем данные», и текст согласия; её кнопка — ob:agree.
    if (sub === 'agree' && step === 'ob_consent') return out('consent_namecheck');
    if (sub === 'details' && step === 'ob_consent') return out('show_details');
    if (sub === 'understood' && step === 'ob_details') return out('consent_namecheck');
    // Ревью W50 круг 1: decline тоже привязываем к шагам (consent/details),
    // иначе сессионно-пустой ob:decline чистит чужую сессию и шлёт отказ.
    if (sub === 'decline' && (step === 'ob_consent' || step === 'ob_details')) return out('declined');
    // Ручной ввод имени приходит с карточки подозрительного имени
    // (onb.suspect): кнопкой ob:fixname (шаг ob_name → show_ask_name) или
    // сразу текстом (W133: текст на ob_name — тоже text_name, кнопка
    // необязательна).
    if (sub === 'fixname' && step === 'ob_name') return out('show_ask_name');
    if (starts(sub, 'city:') && step === 'ob_city') {
      const city = sub.slice(5);
      // ADR-0046: город — последнее поле; спрашиваем «Вы из Ташкента?».
      // «Да» — сразу finish с городом, «Нет» — свободный ввод
      // (show_ask_city → ob_await_city). W120: алиасы старых колбэков
      // (Tashkent/Almaty/write) сняты — прочее значение уходит в `ignore`.
      if (city === 'yes') return out('finish', { city: 'Ташкент' });
      if (city === 'no') return out('show_ask_city');
    }
    if (sub === 'register' && step === 'ob_register') return out('finish_lite');
    return out('ignore');
  }
  if (text !== '') {
    // W133: имя пишут и сразу текстом, не нажимая «Написать имя»
    // (шаг ob_name) — принимаем так же, как с ob_await_name.
    if (step === 'ob_await_name' || step === 'ob_name') return out('text_name');
    if (step === 'ob_await_work') return out('text_work');
    // ADR-0043/ADR-0046: город текстом — тоже сразу finish.
    if (step === 'ob_await_city') return out('finish', { city: text });
  }
  return out('ignore');
};
